def y(v):
    return json.dumps(v, ensure_ascii=False)

for p in P:
    for lang in ('es', 'en'):
        d = p[lang]
        img = f'../../../assets/projects/{p["slug"]}'
        lines = ['---',
          f'title: {y(d["title"])}', f'order: {p["order"]}', f'featured: {str(p["featured"]).lower()}',
          f'year: {p["year"] if p["year"] else "null"}',
          f'categories: {y(d["categories"])}', f'stack: {y(p["stack"])}',
          f'summary: {y(d["summary"])}', f'description: {y(d["description"])}',
          f'url: {y(p["url"])}', f'figma: {y(p["figma"]) if p["figma"] else "null"}',
          f'cover: {y(img + "/cover.webp")}', f'detail: {y(img + "/detail.webp")}', f'mobile: {y(img + "/mobile.webp")}',
          f'project: {y(d["project"])}', f'challenge: {y(d["challenge"])}', f'built: {y(d["built"])}',
          '---', '']
        out = ROOT / lang / f'{p["slug"]}.md'
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_text('\n'.join(lines), encoding='utf-8')
print('ok', len(P) * 2)
